-- GIB: reduce public Data API EXECUTE privileges on privileged functions.
-- Generated by `supabase migration new tighten_gib_rpc_privileges`.
-- SOURCE-ONLY PROPOSAL: Do not apply to production until tested and approved.
--
-- Postgres/Supabase may grant EXECUTE to PUBLIC and directly to anon and
-- authenticated. Removing PUBLIC alone is insufficient.
--
-- An authenticated user must still be able to use the three intentional
-- per-user RPC/policy helpers, while a request with no user session may not.

-- Trigger-only SECURITY DEFINER functions have no direct client API use.
revoke execute on function public.add_crew_owner_as_member()
  from public, anon, authenticated;
revoke execute on function public.handle_new_user()
  from public, anon, authenticated;

-- Authenticated-only operations: revoke direct anon grants.
-- Explicitly preserve the grants used by the app/RLS policies.
revoke execute on function public.can_read_profile(uuid)
  from public, anon;
grant execute on function public.can_read_profile(uuid)
  to authenticated;

revoke execute on function public.find_crew_invitee_by_phone(uuid, text)
  from public, anon;
grant execute on function public.find_crew_invitee_by_phone(uuid, text)
  to authenticated;

revoke execute on function public.get_my_private_profile()
  from public, anon;
grant execute on function public.get_my_private_profile()
  to authenticated;

-- Ordinary trigger helpers do not need to be exposed as RPC endpoints.
revoke execute on function public.set_updated_at()
  from public, anon, authenticated;
revoke execute on function public.set_participant_status_updated_at()
  from public, anon, authenticated;
revoke execute on function public.protect_participant_identity()
  from public, anon, authenticated;

-- Pin the search path for three functions flagged by the database advisor.
-- These functions use NEW/OLD and built-ins; they contain no unqualified
-- application-table references.
alter function public.set_updated_at() set search_path = '';
alter function public.set_participant_status_updated_at() set search_path = '';
alter function public.protect_participant_identity() set search_path = '';

-- Do not revoke EXECUTE on the private.is_crew_* or other internal RLS
-- helpers blindly: authenticated RLS policies rely on those functions.
-- The private schema itself is not exposed to anon/API callers.
